using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurifyAction", menuName = "Data/Battle/Battle Actions/Purification Actions/Purify Action")]
public class PurifyAction : BattleAction
{
	[Header("Soul Heat")]
	[SerializeField]
	private SoulHeat soulHeat;

	[Header("Random purify")]
	[SerializeField]
	private bool randomPurify;

	[Header("Platinum Star")]
	[SerializeField]
	private bool ignoreModifiedPurifyAmount;

	private bool ignoreResetWickedCard;

	private BattleHandler battleHandler => ReferenceSingleton<BattleHandler>.Instance;

	private GameObject playerGameObject => battleHandler.PlayerGameObject;

	public void ResetIgnoreResetWickedCard()
	{
		ignoreResetWickedCard = false;
	}

	public void CastTargetAmountForAreaConfuse(GameObject target, int purifyAmount, GameObject source)
	{
		ignoreResetWickedCard = true;
		CastTargetAmount(target, purifyAmount, source);
	}

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		SingleTargetCast(target, purifyAmount, source, randomPurify ? CorruptionPurifyModifierEnum.RANDOMPURIFYRANDOMCONFUSE : CorruptionPurifyModifierEnum.NONE);
		if (battleHandler.IsSourcePlayer(source) && randomPurify && ReferenceSingleton<AustraOmensHandler>.Instance.ApianLampOmenDataActive)
		{
			SingleTargetCast(ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget, purifyAmount, source, CorruptionPurifyModifierEnum.RANDOMPURIFYRANDOMCONFUSE);
		}
		if (battleHandler.IsSourcePlayer(source) && randomPurify)
		{
			if (battleHandler.IsTargetPlayer(target) || battleHandler.IsTargetSentinel(target))
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RandomPurifyAmount++;
			}
			if (battleHandler.IsTargetPlayer(ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget) || battleHandler.IsTargetSentinel(ReferenceSingleton<BattleHandler>.Instance.RandomPurifySecondTarget))
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RandomPurifyAmount++;
			}
		}
	}

	private void SingleTargetCast(GameObject target, int purifyAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		if (battleHandler.IsSourcePlayer(source))
		{
			ReferenceSingleton<AustraOmensHandler>.Instance.ActivateSafeCriticalOmen();
		}
		List<GameObject> list = new List<GameObject>();
		list.Add(target);
		DefaultCast(purifyAmount, list, source, delegate(int modifiedPurifyAmount)
		{
			CheckIfSecondActionIsDrawActionIfNotTryTryEnterActionQueueState();
			DefaultCastAction(target, modifiedPurifyAmount, source, corruptionPurifyModifierEnum);
			if (!ignoreResetWickedCard)
			{
				ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
			}
		});
		ReferenceSingleton<AustraOmensHandler>.Instance.DeactivateSafeCriticalOmen();
	}

	private void CheckIfSecondActionIsDrawActionIfNotTryTryEnterActionQueueState()
	{
		if (battleHandler.CurrentActionInstance != null)
		{
			ActionFace actionFace = battleHandler.CurrentActionInstance.ActionFace;
			if (actionFace.EnableSecondAction)
			{
				if (actionFace.SecondBattleAction.name != "DrawAction")
				{
					TryEnterActionQueueState();
				}
				else if (!actionFace.SecondBattleAction.CheckConditionToBeCasted(playerHand: true, DiceOwnerEnum.PLAYER))
				{
					TryEnterActionQueueState();
				}
			}
			else
			{
				TryEnterActionQueueState();
			}
		}
		else
		{
			TryEnterActionQueueState();
		}
	}

	private void TryEnterActionQueueState()
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueNormalPurifyCorruptCoroutineAction();
		instance.SetState(instance.ActionsQueueState);
	}

	public void CastTargetAmountPierce(GameObject target, int purifyAmount, GameObject source)
	{
		SingleTargetCast(target, purifyAmount, source, CorruptionPurifyModifierEnum.PIERCE);
	}

	public void CastTargetAmountXTime(GameObject target, int purifyAmount, GameObject source)
	{
		List<GameObject> list = new List<GameObject>();
		list.Add(target);
		DefaultCast(purifyAmount, list, source, delegate(int modifiedPurifyAmount)
		{
			DefaultCastAction(target, modifiedPurifyAmount, source);
		});
	}

	public void CastTargetAmountChanting(GameObject target, int purifyAmount, GameObject source)
	{
		if (battleHandler.IsSourcePlayer(source))
		{
			ReferenceSingleton<AustraOmensHandler>.Instance.ActivateSafeCriticalOmen();
		}
		List<GameObject> list = new List<GameObject>();
		list.Add(target);
		DefaultCast(purifyAmount, list, source, delegate(int modifiedPurifyAmount)
		{
			CheckIfSecondActionIsDrawActionIfNotTryTryEnterActionQueueState();
			DefaultCastAction(target, modifiedPurifyAmount, source);
			ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		}, chanting: true);
		ReferenceSingleton<AustraOmensHandler>.Instance.DeactivateSafeCriticalOmen();
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int purifyAmount, GameObject source)
	{
		AreaTargetCast(targets, purifyAmount, source);
	}

	private void AreaTargetCast(List<GameObject> targets, int purifyAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		if (battleHandler.IsSourcePlayer(source))
		{
			ReferenceSingleton<AustraOmensHandler>.Instance.ActivateSafeCriticalOmen();
		}
		DefaultCast(purifyAmount, targets, source, delegate(int modifiedPurifyAmount)
		{
			CheckIfSecondActionIsDrawActionIfNotTryTryEnterActionQueueState();
			for (int i = 0; i < targets.Count; i++)
			{
				DefaultCastAction(targets[i], modifiedPurifyAmount, source, corruptionPurifyModifierEnum);
			}
			ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		});
		ReferenceSingleton<AustraOmensHandler>.Instance.DeactivateSafeCriticalOmen();
	}

	public void AreaCastTargetAmountPierce(List<GameObject> targets, int purifyAmount, GameObject source)
	{
		AreaTargetCast(targets, purifyAmount, source, CorruptionPurifyModifierEnum.PIERCE);
	}

	public void AreaCastTargetAmountXTime(List<GameObject> targets, int purifyAmount, GameObject source)
	{
		DefaultCast(purifyAmount, targets, source, delegate(int modifiedPurifyAmount)
		{
			for (int i = 0; i < targets.Count; i++)
			{
				DefaultCastAction(targets[i], modifiedPurifyAmount, source);
			}
		});
	}

	public void AreaCastTargetAmountChanting(List<GameObject> targets, int purifyAmount, GameObject source)
	{
		DefaultCast(purifyAmount, targets, source, delegate(int modifiedPurifyAmount)
		{
			CheckIfSecondActionIsDrawActionIfNotTryTryEnterActionQueueState();
			for (int i = 0; i < targets.Count; i++)
			{
				DefaultCastAction(targets[i], modifiedPurifyAmount, source);
			}
			ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		}, chanting: true);
	}

	public void AreaTargetCastEffectBasedAreaPurify(List<GameObject> targets, List<int> purifyAmounts, GameObject source)
	{
		CheckIfSecondActionIsDrawActionIfNotTryTryEnterActionQueueState();
		if (battleHandler.IsSourcePlayer(source))
		{
			soulHeat.ModifySoulHeat(1);
		}
		int num = 0;
		if (!ignoreModifiedPurifyAmount)
		{
			num = ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyBlazarDiskModifier(1);
		}
		List<int> list = new List<int>();
		for (int i = 0; i < purifyAmounts.Count; i++)
		{
			if (!ignoreModifiedPurifyAmount)
			{
				list.Add(GetModifiedPurifyAmount(purifyAmounts[i], chanting: false, effectBasedAreaPurify: true, source) * num);
			}
			else
			{
				list.Add(purifyAmounts[i]);
			}
		}
		for (int j = 0; j < targets.Count; j++)
		{
			DefaultCastAction(targets[j], list[j], source);
		}
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		PlaySFXPlayerDealPurifyOmensAnMinimize(targets, source);
	}

	private void DefaultCast(int purifyAmount, List<GameObject> targets, GameObject source, Action<int> defaultCastAction, bool chanting = false)
	{
		int obj = purifyAmount;
		if (!ignoreModifiedPurifyAmount)
		{
			obj = GetModifiedPurifyAmount(purifyAmount, chanting, effectBasedAreaPurify: false, source);
		}
		defaultCastAction(obj);
		PlaySFXPlayerDealPurifyOmensAnMinimize(targets, source);
	}

	public int GetModifiedPurifyAmount(int purifyAmount, bool chanting, bool effectBasedAreaPurify, GameObject source)
	{
		int num = purifyAmount;
		if (battleHandler.IsSourcePlayer(source))
		{
			num = ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyStartModifiers(num);
			num = CheckFrenzy(num);
			num = CheckFireBreath(num);
			num = CheckBloodySolstice(num);
			if (!effectBasedAreaPurify)
			{
				soulHeat.ModifySoulHeat(1);
			}
			IsPlayerChantingCheckIfRemove(chanting);
			if (!effectBasedAreaPurify)
			{
				num = ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyBlazarDiskModifier(num);
			}
			num = CheckCritical(num, null);
		}
		if (battleHandler.IsSourceCompanions(source) && ReferenceSingleton<AustraOmensHandler>.Instance.HiveModuleOmenActive)
		{
			num = CheckCritical(num, source);
		}
		return num;
	}

	private void PlaySFXPlayerDealPurifyOmensAnMinimize(List<GameObject> targets, GameObject source)
	{
		PlaySFX();
		ActivateOnPlayerDealPurifyOmens(source, targets);
		CheckMinimizeOnPlayer(source);
	}

	private void CheckMinimizeOnPlayer(GameObject source)
	{
		if (battleHandler.IsSourcePlayer(source))
		{
			playerGameObject.GetComponent<PlayerEffects>().IsMinimizeEffectActiveAndDecreaseEffect();
		}
	}

	private int CheckCritical(int purifyAmount, GameObject source)
	{
		return playerGameObject.GetComponent<PlayerEffects>().IsPlayerCriticalCheckCritical(purifyAmount, fierceSquall: false, sentPur: false, source);
	}

	private int CheckFrenzy(int purifyAmount)
	{
		if (playerGameObject.GetComponent<PlayerEffects>().IsPlayerFrenzy())
		{
			return purifyAmount * 2;
		}
		return purifyAmount;
	}

	private int CheckFireBreath(int purifyAmount)
	{
		return purifyAmount + playerGameObject.GetComponent<PlayerEffects>().IsPlayerFireBreathGetAmount();
	}

	private int CheckBloodySolstice(int purifyAmount)
	{
		if (playerGameObject.GetComponent<PlayerEffects>().IsPlayerBloodySolstice())
		{
			return purifyAmount * 2;
		}
		return purifyAmount;
	}

	public void IsPlayerChantingCheckIfRemove(bool chanting)
	{
		if (chanting)
		{
			return;
		}
		if (ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance != null)
		{
			if (ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance is DiceInstance)
			{
				if ((ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance as DiceInstance).Dice.DiceTier == ReferenceSingleton<AssetsReference>.Instance.StarterDieTier)
				{
					return;
				}
			}
			else if (ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance is RuneInstance)
			{
				return;
			}
		}
		playerGameObject.GetComponent<PlayerEffects>().IsPlayerChantingActiveRemove();
	}

	private void ActivateOnPlayerDealPurifyOmens(GameObject source, List<GameObject> targets)
	{
		if (!battleHandler.IsSourcePlayer(source))
		{
			return;
		}
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurify();
		bool flag = false;
		for (int i = 0; i < targets.Count; i++)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealOnPlayerDealPurifyWithTarget(targets[i]);
			if (battleHandler.IsTargetEnemy(targets[i]))
			{
				flag = true;
				break;
			}
		}
		if (flag)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnEnemies();
		}
	}

	private void DefaultCastAction(GameObject target, int modifiedPurifyAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		CheckFlammableChakramAndInflammableChakram(target, source);
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		ActivateOnPlayerDealPurifyOmensMultipleActivationAtOnce(target, source);
		target.GetComponent<CorruptionStats>().Purify(modifiedPurifyAmount, source, corruptionPurifyModifierEnum);
		ReferenceSingleton<MiscOmensHandler>.Instance.WickedsCardOmenAction?.Invoke(source, target);
	}

	private void CheckFlammableChakramAndInflammableChakram(GameObject target, GameObject source)
	{
		if (battleHandler.IsSourcePlayer(source))
		{
			playerGameObject.GetComponent<PlayerEffects>().IsFlammableChakramActiveApplyRelief(target);
			ReferenceSingleton<SothisOmensHandler>.Instance.FireIceCreamOmenAction?.Invoke(target);
		}
	}

	private void ActivateOnPlayerDealPurifyOmensMultipleActivationAtOnce(GameObject target, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && ReferenceSingleton<BattleHandler>.Instance.IsTargetSentinel(target))
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnSentinels();
		}
	}
}
